static uint16_t embi_bind_svg_iface_for_tag(embi_atom local)
{
    embi_str s = embi_atom_str(local);
    int lo = 0, hi = 32 - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        uint32_t n = embi_bind_svg_tags[mid].len < s.len ? embi_bind_svg_tags[mid].len : s.len;
        int cmp = SDL_memcmp(s.ptr, embi_bind_svg_tags[mid].tag, n);
        if (cmp == 0) cmp = (s.len > embi_bind_svg_tags[mid].len) - (s.len < embi_bind_svg_tags[mid].len);
        if (cmp == 0) return embi_bind_svg_tags[mid].iface;
        if (cmp < 0) hi = mid - 1; else lo = mid + 1;
    }
    return EMBI_IF_SVGElement;
}
#endif

uint16_t embi_bind_iface_for_tag(uint8_t ns, embi_atom local)
{
#if EMBER_SVG
    if (ns == EMBI_NS_SVG) return embi_bind_svg_iface_for_tag(local);
#else
    if (ns == EMBI_NS_SVG) return EMBI_IF_SVGElement;
#endif
    if (ns != EMBI_NS_HTML) return EMBI_IF_Element;
    embi_str s = embi_atom_str(local);
    int lo = 0, hi = 73 - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        uint32_t n = embi_bind_tags[mid].len < s.len ? embi_bind_tags[mid].len : s.len;
        int cmp = SDL_memcmp(s.ptr, embi_bind_tags[mid].tag, n);
        if (cmp == 0) cmp = (s.len > embi_bind_tags[mid].len) - (s.len < embi_bind_tags[mid].len);
        if (cmp == 0) return embi_bind_tags[mid].iface;
        if (cmp < 0) hi = mid - 1; else lo = mid + 1;
    }
    for (uint32_t i = 0; i < s.len; i++) if (s.ptr[i] == '-') return EMBI_IF_HTMLElement;
    return EMBI_IF_HTMLUnknownElement;
}
